"""Turn compiled code into a PlatformIO project or a native simulator executable."""

from __future__ import annotations

import hashlib
import io
import os
import shutil
import subprocess
import sys
import zipfile
from pathlib import Path

from .boards import BoardDef
from .compiler import CompileResult

RUNTIME_DIR = Path(__file__).parent / "runtime"
SIM_DIR = RUNTIME_DIR / "sim"


def platformio_ini(board: BoardDef, result: CompileResult, baud: int) -> str:
    pio = board.platformio
    env = pio.get("board", board.id)
    lines = [
        "; Generated by FBD Studio",
        f"[env:{env}]",
        f"platform = {pio['platform']}",
        f"board = {pio.get('board', board.id)}",
        f"framework = {pio.get('framework', 'arduino')}",
        f"monitor_speed = {baud}",
    ]
    for key, val in {**pio, **result.platformio}.items():
        if key not in ("platform", "board", "framework"):
            lines.append(f"{key} = {val}")
    if board.build_flags:
        lines.append("build_flags = " + " ".join(board.build_flags))
    if result.lib_deps:
        lines.append("lib_deps =")
        lines.extend(f"    {d}" for d in result.lib_deps)
    return "\n".join(lines) + "\n"


def project_files(board: BoardDef, result: CompileResult, baud: int) -> dict[str, str]:
    assert result.code is not None
    files = {
        "platformio.ini": platformio_ini(board, result, baud),
        "src/main.cpp": result.code,
    }
    for header in sorted(RUNTIME_DIR.glob("*.h")):  # plcrt.h and the helpers used by communication blocks
        files[f"include/{header.name}"] = header.read_text(encoding="utf-8")
    return files


def write_pio_project(out_dir: Path, board: BoardDef, result: CompileResult, baud: int) -> Path:
    for rel, content in project_files(board, result, baud).items():
        path = out_dir / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        if not path.exists() or path.read_text(encoding="utf-8") != content:
            path.write_text(content, encoding="utf-8")  # keep mtimes for incremental builds
    return out_dir


def zip_pio_project(name: str, board: BoardDef, result: CompileResult, baud: int) -> bytes:
    buf = io.BytesIO()
    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:
        for rel, content in project_files(board, result, baud).items():
            z.writestr(f"{name}/{rel}", content)
    return buf.getvalue()


def find_pio() -> str | None:
    candidates = [
        shutil.which("pio"),
        shutil.which("platformio"),
        str(Path(sys.executable).parent / ("pio.exe" if os.name == "nt" else "pio")),
        str(Path.home() / ".platformio" / "penv" / ("Scripts" if os.name == "nt" else "bin") / ("pio.exe" if os.name == "nt" else "pio")),
    ]
    for c in candidates:
        if c and Path(c).is_file():
            return c
    return None


def pio_command(project_dir: Path, upload: bool, port: str | None) -> list[str]:
    pio = find_pio()
    if pio is None:
        raise RuntimeError(
            "PlatformIO was not found. Install it with:  pip install platformio   "
            "(or install the PlatformIO IDE extension), then try again."
        )
    cmd = [pio, "run", "-d", str(project_dir)]
    if upload:
        cmd += ["-t", "upload"]
        if port:
            cmd += ["--upload-port", port]
    return cmd


def find_cxx() -> str | None:
    for name in ("g++", "clang++", "c++"):
        p = shutil.which(name)
        if p:
            return p
    return None


def build_sim(result: CompileResult, cache_dir: Path) -> Path:
    """Compile the program for the PC. Returns the executable path (cached by content)."""
    assert result.code is not None
    cxx = find_cxx()
    if cxx is None:
        raise RuntimeError("The simulator needs a C++ compiler (g++ or clang++). Please install one.")
    sources = result.code + (RUNTIME_DIR / "plcrt.h").read_text() + (SIM_DIR / "sim_main.cpp").read_text() + (SIM_DIR / "Arduino.h").read_text()
    key = hashlib.sha1(sources.encode()).hexdigest()[:12]
    work = cache_dir / key
    exe = work / ("sim.exe" if os.name == "nt" else "sim")
    if exe.exists():
        return exe
    work.mkdir(parents=True, exist_ok=True)
    (work / "main.cpp").write_text(result.code, encoding="utf-8")
    cmd = [
        cxx, "-std=c++11", "-O1", "-w",
        f"-I{SIM_DIR}", f"-I{RUNTIME_DIR}",
        str(work / "main.cpp"), str(SIM_DIR / "sim_main.cpp"),
        "-o", str(exe), "-pthread",
    ]
    proc = subprocess.run(cmd, capture_output=True, text=True)
    if proc.returncode != 0:
        raise RuntimeError("Simulator compile failed:\n" + (proc.stderr or proc.stdout)[-4000:])
    _prune_cache(cache_dir, keep=8)
    return exe


def _prune_cache(cache_dir: Path, keep: int) -> None:
    dirs = sorted((d for d in cache_dir.iterdir() if d.is_dir()), key=lambda d: d.stat().st_mtime, reverse=True)
    for d in dirs[keep:]:
        shutil.rmtree(d, ignore_errors=True)
